EXISTS(SELECT 1 FROM json_tree(NEW.metadata) j WHERE typeof(j.key)='text' GROUP BY j.parent,j.key HAVING count(*)>1)
 OR EXISTS(SELECT 1 FROM json_tree(NEW.metadata) j WHERE j.key IN ('acquisition_root_id','completion_marker_id','content_id','fetch_occurrence_uuidv4','fetch_occurrence_uuidv4s','git_object_id','parsed_result_uuidv4','parsed_result_uuidv4s','parser_profile_uuidv4','parser_profile_verification_uuidv4','payload','resume_scope_id','selection_decision_uuidv4','selection_predecessors','source_id','source_input_uuidv4','stable_scope','text_body_id'))
 OR EXISTS(SELECT 1 FROM json_tree(NEW.metadata) j WHERE (j.key GLOB '*_uuidv4' OR j.key GLOB '*_uuidv4s') AND j.key NOT IN ('change_request_event_uuidv4','change_request_id','change_request_ids','child_fetch_collection_id','code_assessment_id','code_listing_id','completion_marker_uuidv4','completion_marker_uuidv4s','fetch_collection_id','fetch_collection_ids','git_acquisition_id','git_acquisition_ids','parent_fetch_collection_id','relation_uuidv4','repository_binding_id','repository_endpoint_id','repository_uuidv4','service_instance_uuidv4','source_registration_uuidv4'))
 OR EXISTS(SELECT 1 FROM json_tree(NEW.metadata) j WHERE j.key='change_request_event_uuidv4' AND j.type<>'null' AND (j.type<>'text' OR NOT (length(j.value)=36 AND length(CAST(j.value AS BLOB))=36 AND substr(j.value,9,1)='-' AND substr(j.value,14,1)='-' AND substr(j.value,19,1)='-' AND substr(j.value,24,1)='-' AND length(replace(j.value,'-',''))=32 AND replace(j.value,'-','') NOT GLOB '*[^0-9a-f]*' AND substr(j.value,15,1)='4' AND substr(j.value,20,1) IN ('8','9','a','b')) OR NOT EXISTS(SELECT 1 FROM change_request_events t WHERE t.change_request_event_uuidv4=j.value)))
