','provider_repository_id','provider_resource_id','query_kind','reported_count','rest_page_size','sort','state') OR (CASE md1.key WHEN 'base' THEN ((md1.type<>'null' AND (md1.type<>'object' OR EXISTS(SELECT 1 FROM json_each(CASE WHEN md1.type='object' THEN md1.value ELSE '{}' END) md2 WHERE md2.key NOT IN ('sha') OR (CASE md2.key WHEN 'sha' THEN (md2.type NOT IN ('null','text')) ELSE 1 END))))) WHEN 'base_oid' THEN (md1.type NOT IN ('null','text')) WHEN 'completion_marker_uuidv4' THEN (md1.type NOT IN ('null','text')) WHEN 'direction' THEN (md1.type NOT IN ('null','text')) WHEN 'graphql_page_size' THEN (md1.type NOT IN ('integer','null')) WHEN 'head' THEN ((md1.type<>'null' AND (md1.type<>'object' OR EXISTS(SELECT 1 FROM json_each(CASE WHEN md1.type='object' THEN md1.value ELSE '{}' END) md2 WHERE md2.key NOT IN ('sha') OR (CASE md2.key WHEN 'sha' THEN (md2.type NOT IN ('null','text')) ELSE 1 END))))) WHEN 'head_oid' THEN (md1.type NOT IN ('null','text')) WHEN 'incremental_endpoint' THEN (md1.type NOT IN ('null','text')) WHEN 'kind' THEN (md1.type NOT IN ('null','text')) WHEN 'name' THEN (md1.type NOT IN ('null','text')) WHEN 'number' THEN (md1.type NOT IN ('integer','null')) WHEN 'object_format' THEN (md1.type NOT IN ('null','text')) WHEN 'owner' THEN (md1.type NOT IN ('null','text')) WHEN 'parent_fetch_collection_id' THEN (md1.type NOT IN ('null','text')) WHEN 'parent_observed_at_us' THEN (md1.type NOT IN ('integer','null')) WHEN 'permissions' THEN ((md1.type<>'null' AND (md1.type<>'array' OR EXISTS(SELECT 1 FROM json_each(CASE WHEN md1.type='array' THEN md1.value ELSE '[]' END) md2 WHERE md2.type NOT IN ('null','text'))))) WHEN 'provider_issue_id' THEN (md1.type NOT IN ('null','text')) WHEN 'provider_issue_number' THEN (md1.type NOT IN ('integer','null')) WHEN 'provider_repository_id' THEN (md1.type NOT IN ('null','text')) WHEN 'provider_resource_id' THEN (md1.type NOT IN ('null','text')) WHEN 'query_kind' THEN (md1.type NOT IN ('null','text')) WHEN 'reported_count' THEN (md1.type NOT IN ('integer','null')) WHEN 'rest_page_size' THEN (md1.type NOT IN ('integer','null')) WHEN 'sort' THEN (md1.type NOT IN ('null','text')) WHEN 'state' THEN (md1.type NOT IN ('null','text')) ELSE 1 END))))) WHEN 'selected_repositories' THEN ((md0.type<>'null' AND (md0.type<>'array' OR EXISTS(SELECT 1 FROM json_each(CASE WHEN md0.type='array' THEN md0.value ELSE '[]' END) md1 WHERE md1.type NOT IN ('null','text'))))) WHEN 'service_instance_uuidv4' THEN (md0.type NOT IN ('null','text')) WHEN 'source_registration_uuidv4' THEN (md0.type NOT IN ('null','text')) WHEN 'visibility' THEN (md0.type NOT IN ('null','text')) ELSE 1 END))))
