CREATE TRIGGER json_review_resources_field_evidence_json_insert BEFORE INSERT ON review_resources
WHEN NEW.field_evidence_json IS NOT NULL AND CASE WHEN NOT json_valid(NEW.field_evidence_json) THEN 1 WHEN json_type(NEW.field_evidence_json)<>'object' THEN 1 ELSE (
EXISTS(SELECT 1 FROM json_each(NEW.field_evidence_json) e GROUP BY e.key HAVING count(*)>1)
 OR EXISTS(SELECT 1 FROM json_each(NEW.field_evidence_json) e WHERE CASE WHEN NOT json_valid(e.key) THEN 1 WHEN json_type(e.key)<>'array' THEN 1 ELSE (json_array_length(e.key)=0 OR (SELECT json_group_array(p.value) FROM json_each(e.key) p)<>e.key OR EXISTS(SELECT 1 FROM json_each(e.key) p WHERE p.type<>'text') OR json_extract(e.key,'$[0]') NOT IN ('author','body','current_position','deleted','diff_hunk','in_reply_to_provider_resource_id','metadata','original_commit_oid','original_position','raw_path','review_provider_resource_id','review_thread_provider_resource_id','state','submitted_at_us','target_commit_oid','url') OR (json_array_length(e.key)>1 AND json_extract(e.key,'$[0]')<>'metadata')) END)
 OR EXISTS(WITH RECURSIVE paths(path,value,type) AS (SELECT json_array('metadata'),NEW.metadata,'object' UNION ALL SELECT json_insert(p.path,'$[#]',j.key),j.value,j.type FROM paths p JOIN json_each(CASE WHEN p.type='object' THEN p.value ELSE '{}' END) j WHERE p.type='object') SELECT 1 FROM json_each(NEW.field_evidence_json) e WHERE json_extract(e.key,'$[0]')='metadata' AND NOT EXISTS(SELECT 1 FROM paths p WHERE p.path=e.key))
 OR EXISTS(SELECT 1 FROM json_each(NEW.field_evidence_json) e JOIN json_each(e.key) depth WHERE json_extract(e.key,'$[0]')='metadata' AND CAST(depth.key AS INTEGER)>0 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.field_evidence_json) a WHERE a.key=(SELECT json_group_array(p.value) FROM json_each(e.key) p WHERE CAST(p.key AS INTEGER)<CAST(depth.key AS INTEGER))))
