EXISTS(SELECT 1 FROM json_tree(NEW.metadata) j WHERE typeof(j.key)='text' GROUP BY j.parent,j.key HAVING count(*)>1)
 OR (json_type(NEW.metadata)<>'null' AND (json_type(NEW.metadata)<>'object' OR EXISTS(SELECT 1 FROM json_each(CASE WHEN json_type(NEW.metadata)='object' THEN NEW.metadata ELSE '{}' END) md0 WHERE md0.key NOT IN ('') OR (1))))
) END BEGIN SELECT RAISE(ABORT,'JSON contract violation: review_thread_state.metadata'); END;
